/**
 * Generates src/catalog/brand-icons.ts from simple-icons.
 *
 * Run with: npx tsx scripts/generate-brand-icons.ts
 *
 * Why this is a generated file rather than a runtime dependency on
 * simple-icons: the package is 25 MB of SVG for 3466 brands, and we need 100 of
 * them. Inlining only the paths we use keeps the bundle small and makes the
 * icon set reviewable in one place.
 *
 * Coverage is not complete. simple-icons does not carry every vendor, and some
 * brands are unavailable from this environment entirely. Products without an
 * entry here fall back to their category glyph, so the map stays consistent
 * rather than showing a logo for half the nodes and nothing for the rest.
 */
import { writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { PRODUCTS } from '../src/catalog/index';
import * as si from 'simple-icons';

const __dirname = resolve(fileURLToPath(import.meta.url), '..');

const ns = si as unknown as Record<string, unknown>;
const all = (ns.default && typeof ns.default === 'object' ? ns.default : ns) as Record<
  string,
  { title?: string; slug?: string; path?: string }
>;

function normalise(value: string): string {
  return value.toLowerCase().replace(/&/g, 'and').replace(/[^a-z0-9]/g, '');
}

const byTitle = new Map<string, string>();
for (const [slug, icon] of Object.entries(all)) {
  const title = icon?.title;
  if (title) byTitle.set(normalise(title), slug);
}

/**
 * Catalog name -> simple-icons title. Only names that differ from the catalog
 * entry are listed. Kept here rather than in the catalog so the generated icon
 * map stays the single place that documents which brand each product shows.
 */
const ALIASES: Record<string, string> = {
  'MongoDB Atlas': 'MongoDB',
  CockroachDB: 'Cockroach Labs',
  BigQuery: 'Google BigQuery',
  'Grafana Cloud': 'Grafana',
  'Splunk Observability': 'Splunk',
  'Elastic (ELK)': 'Elastic',
  'Atlassian Statuspage': 'Atlassian',
  'PayPal and Braintree': 'PayPal',
  'Firebase Cloud Messaging': 'Firebase',
  'Google Vertex AI': 'Google Vertex',
  'AWS Bedrock': 'Amazon Bedrock',
  'Amazon SQS and SNS': 'Amazon SQS',
  'Amazon SES': 'Amazon SES',
  'Amazon Cognito': 'Amazon Cognito',
  'Amazon DynamoDB': 'Amazon DynamoDB',
  'OpenAI API': 'OpenAI',
  'Anthropic API': 'Anthropic',
  'HashiCorp Vault': 'HashiCorp Vault',
  'Wise Platform': 'Wise',
  'Together AI': 'Together AI',
};

const entries: { id: string; path: string }[] = [];
const missing: string[] = [];

for (const product of PRODUCTS) {
  const candidates = [product.name, ALIASES[product.name]].filter(Boolean) as string[];
  const slug = candidates.map(normalise).map((c) => byTitle.get(c)).find(Boolean);
  const icon = slug ? all[slug] : undefined;
  const path = icon?.path;

  if (path) {
    entries.push({ id: product.id, path });
  } else {
    missing.push(product.name);
  }
}

const lines = [
  '/**',
  ' * Brand marks for individual products, generated by scripts/generate-brand-icons.ts.',
  ' *',
  ' * Each value is an SVG path on a 24x24 viewBox, matching the category icons.',
  ' * Draw them with `new Path2D(path)` and scale to fit.',
  ' *',
  ` * ${entries.length} of ${PRODUCTS.length} products have a brand mark. The rest fall`,
  ' * back to their category glyph, so every node has something to show and the map',
  ' * does not look half-finished.',
  ' *',
  ' * Regenerate with: npx tsx scripts/generate-brand-icons.ts',
  ' */',
  'export const BRAND_ICONS: Record<string, string> = {',
  ...entries.map((e) => `  ${JSON.stringify(e.id)}: ${JSON.stringify(e.path)},`),
  '};',
  '',
  '/** The SVG path for a product\'s brand mark, if one exists. */',
  'export function getBrandIcon(productId: string): string | undefined {',
  '  return BRAND_ICONS[productId];',
  '}',
  '',
].join('\n');

const out = resolve(__dirname, '../src/catalog/brand-icons.ts');
writeFileSync(out, lines);

console.log(`wrote ${entries.length} brand icons -> src/catalog/brand-icons.ts`);
console.log(`${missing.length} products have no brand mark:`);
for (const name of missing) console.log('  -', name);
